class Solution {
public:
    int maximumEnergy(vector<int>& energy, int k) {
        int n = (int)energy.size();
        int best = INT_MIN;
        for (int i = n - 1; i >= 0; i--) {
            if (i + k < n) {
                energy[i] += energy[i + k];
            }
            if (energy[i] > best) {
                best = energy[i];
            }
        }
        return best;
    }
};
